$ErrorActionPreference = 'Stop'

# VETRA Care Android PWA icon refresh.
# Creates fresh-versioned icon URLs so Android/Chrome do not reuse older cached icon files.
$root = (Get-Location).Path
$manifestPath = Join-Path $root 'app/client-interface/manifest.ts'
$layoutPath = Join-Path $root 'app/client-interface/layout.tsx'
if (-not (Test-Path (Join-Path $root 'package.json'))) {
  throw 'Run this script from the VETRA project root (the folder containing package.json).'
}
if (-not (Test-Path $manifestPath)) { throw "Missing file: $manifestPath" }
if (-not (Test-Path $layoutPath)) { throw "Missing file: $layoutPath" }

$oldFolder = '/vetra-client-icons-20261012/'
$newFolder = '/vetra-client-icons-20261012-androidfix/'
$backupSuffix = Get-Date -Format 'yyyyMMdd-HHmmss'
Copy-Item $manifestPath "$manifestPath.bak-android-icon-$backupSuffix" -Force
Copy-Item $layoutPath "$layoutPath.bak-android-icon-$backupSuffix" -Force

$manifest = [System.IO.File]::ReadAllText($manifestPath)
$requiredManifestPaths = @(
  '/vetra-client-icons-20261012/icon-192.png',
  '/vetra-client-icons-20261012/icon-512.png',
  '/vetra-client-icons-20261012/icon-maskable-512.png'
)
foreach ($path in $requiredManifestPaths) {
  if (-not $manifest.Contains($path)) {
    throw "Expected icon path was not found in manifest.ts: $path. No changes were written to the manifest."
  }
}

$layout = [System.IO.File]::ReadAllText($layoutPath)
if (-not $layout.Contains('/vetra-client-icons-20261012/icon-192.png') -or
    -not $layout.Contains('/vetra-client-icons-20261012/icon-512.png')) {
  throw 'Expected generic Android/browser icon references were not found in layout.tsx. No changes were written to layout.tsx.'
}

$newPublicDir = Join-Path $root 'public/vetra-client-icons-20261012-androidfix'
New-Item -ItemType Directory -Path $newPublicDir -Force | Out-Null
