[System.IO.File]::WriteAllBytes((Join-Path $newPublicDir 'icon-192.png'), [Convert]::FromBase64String(($icon192Base64 -replace '\s','')))
[System.IO.File]::WriteAllBytes((Join-Path $newPublicDir 'icon-512.png'), [Convert]::FromBase64String(($icon512Base64 -replace '\s','')))
[System.IO.File]::WriteAllBytes((Join-Path $newPublicDir 'icon-maskable-512.png'), [Convert]::FromBase64String(($iconMaskableBase64 -replace '\s','')))

# Update only the three manifest references; the app id/scope and all other behavior remain unchanged.
$manifest = $manifest.Replace('/vetra-client-icons-20261012/icon-192.png', '/vetra-client-icons-20261012-androidfix/icon-192.png')
$manifest = $manifest.Replace('/vetra-client-icons-20261012/icon-512.png', '/vetra-client-icons-20261012-androidfix/icon-512.png')
$manifest = $manifest.Replace('/vetra-client-icons-20261012/icon-maskable-512.png', '/vetra-client-icons-20261012-androidfix/icon-maskable-512.png')

# Refresh generic browser icons for Android/desktop while deliberately keeping the working iPhone Apple icon URL untouched.
$layout = $layout.Replace('/vetra-client-icons-20261012/icon-192.png', '/vetra-client-icons-20261012-androidfix/icon-192.png')
$layout = $layout.Replace('/vetra-client-icons-20261012/icon-512.png', '/vetra-client-icons-20261012-androidfix/icon-512.png')

[System.IO.File]::WriteAllText($manifestPath, $manifest, [System.Text.UTF8Encoding]::new($false))
[System.IO.File]::WriteAllText($layoutPath, $layout, [System.Text.UTF8Encoding]::new($false))

# Post-write verification: all expected files exist and manifest paths resolve to the new asset directory.
$expectedFiles = @('icon-192.png','icon-512.png','icon-maskable-512.png')
foreach ($file in $expectedFiles) {
  $full = Join-Path $newPublicDir $file
  if (-not (Test-Path $full) -or (Get-Item $full).Length -lt 10000) {
    throw "Icon verification failed: $full"
  }
}
$manifestAfter = [System.IO.File]::ReadAllText($manifestPath)
if (-not $manifestAfter.Contains('/vetra-client-icons-20261012-androidfix/icon-maskable-512.png')) {
  throw 'Manifest verification failed after writing.'
}
Write-Host ''
Write-Host 'VETRA Android PWA icon refresh applied.' -ForegroundColor Green
Write-Host 'Updated paths:'
Write-Host '  public/vetra-client-icons-20261012-androidfix/icon-192.png'
Write-Host '  public/vetra-client-icons-20261012-androidfix/icon-512.png'
Write-Host '  public/vetra-client-icons-20261012-androidfix/icon-maskable-512.png'
Write-Host 'Kept the existing Apple/iPhone icon URL unchanged.'
Write-Host "Backup suffix: $backupSuffix"
Write-Host 'Next: run npm run build; if successful, commit and push the manifest, layout, and new public/vetra-client-icons-20261012-androidfix folder.' -ForegroundColor Cyan
